  var r=p.pgRecords[i];
  rows.push({insert_time:r.ts||r.insert_time||new Date().toISOString(),node_id:r.node_id||r.nodeId||null,device_id:r.device_id||r.deviceId||"",device_name:r.device_name||r.deviceName||"",tag_id:r.tag_id||r.tagId||"",tag_address:r.tag_address||r.tagAddr||"",tag_name:r.tag_name||r.tagName||"",register_type:r.register_type||r.regType||"",raw_value:num(r.raw_value),eng_value:num(r.eng_value),unit:r.unit||"",quality:(function(q){if(q==null)return 0;if(typeof q==='number')return q;var s=String(q).toUpperCase();if(s==='GOOD')return 0;if(s==='BAD')return 1;if(s==='UNCERTAIN')return 2;var v=parseInt(s,10);return isNaN(v)?0:v;})(r.quality)  /* 🔧 quality 列为 NUMERIC，字符串 'GOOD' 会导致整批 INSERT 被丢弃 */,host_pc_ip:r.host_pc_ip||r.hostPcIp||""});
}
msg.payload={rows:rows};
return msg;

// 从 edgelink-pg-store 输出更新全局计数
var p = msg.payload || {};
var sc = global.get('edge_pg_success_count') || 0;
var fc = global.get('edge_pg_fail_count') || 0;
if (p.inserted) {
    global.set('edge_pg_success_count', sc + p.inserted);
    global.set('edge_pg_last_write_ts', new Date().toISOString());
    global.set('edge_pg_writing', false);
}
// 🔧 Day7/P1-13: spool 重放的行计入成功（此前 replayed 无人统计，success 长期低估）
if (p.replayed) {
    global.set('edge_pg_success_count', (global.get('edge_pg_success_count') || 0) + p.replayed);
    global.set('edge_pg_last_write_ts', new Date().toISOString());
}
if (p.failed) {
    global.set('edge_pg_fail_count', fc + p.failed);
    global.set('edge_pg_last_error', p.error || '');
}
if (p.buffered != null) {
    global.set('edge_pg_last_latency_ms', p.roundTimeMs || 0);
    // 🔧 Day7: 死指标接线——队列积压上报（01 节点状态汇总的 pgQueueSize 此前恒 0）
    global.set('edge_pg_queue', (p.buffered || 0) + (p.retryBuffered || 0));
}
return msg;

// 数据管道①入口：防重入 guard + 公共上下文（_dp）
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
core.logger.setDebug(st.get('debug'));

var result = msg.payload;
if (!result) return null;

var devId = result.deviceId;
var guard = st.get('procGuard');
var g = guard[devId];
if (g && (Date.now() - g.ts > 30000)) { delete guard[devId]; g = undefined; }  // 过期锁强制释放
if (g) {
    core.logger.debug('DP', 'ProcGuard locked for device ' + devId + ', dropping duplicate');
    node.status({ fill: 'yellow', shape: 'ring', text: 'busy, drop ' + devId });
    return null;
}
guard[devId] = { ts: Date.now() };
st.set('procGuard', guard);

var devices = st.get('devices');
var devInfo = null;
for (var i = 0; i < devices.length; i++) { if (devices[i].id === devId) { devInfo = devices[i]; break; } }

msg._dp = {
    devId: devId,
    devName: result.deviceName || ('PLC-' + devId),
    devInfo: devInfo,
    triggerKind: devInfo ? (devInfo.triggerKind || 1) : 1,
    now: new Date().toISOString(),
    nowMs: Date.now()
};
node.status({ fill: 'blue', shape: 'dot', text: msg._dp.devName });
return msg;

// 数据管道②失败支路：通断状态转换 + 离线事件（仅跳变时）+ 告警入队
var core = global.get('edgeCore');
var st = core.createStore(global);
var dp = msg._dp;

var commStatus = st.get('commStatus');
var t = core.commState.onFail(commStatus[dp.devId], dp.nowMs);
commStatus[dp.devId] = t.status;
st.set('commStatus', commStatus);
dp.becameOffline = t.becameOffline;
dp.consecutiveFails = t.status.consecutiveFails;

if (t.becameOffline) {
    var commPending = st.get('commPending');
    commPending.push({
        deviceId: dp.devId, success: false,
        error: msg.payload.error || 'communication failure',
        consecutiveFails: t.status.consecutiveFails, ts: dp.now
    });
    st.set('commPending', commPending);

    var alerts = st.get('recentAlerts');
    alerts.push({
        alertType: 'PLC_OFFLINE', deviceId: dp.devId, deviceName: dp.devName,
        msg: msg.payload.error || 'communication failure', ts: dp.now
    });
    if (alerts.length > 20) alerts = alerts.slice(-20);
    st.set('recentAlerts', alerts);

    node.status({ fill: 'red', shape: 'ring', text: dp.devName + ' OFFLINE' });
} else {
    node.status({ fill: 'red', shape: 'dot', text: dp.devName + ' fail×' + t.status.consecutiveFails });
}
return msg;

// 数据管道③失败支路出口：PLC_OFFLINE 告警 + lastGood BAD 重发（30s 节流）+ 释放 guard
// 单输出口返回 [msgs数组]：数组逐条扇出（对接 mqtt-out）
var core = global.get('edgeCore');
var st = core.createStore(global);
var dp = msg._dp;
var nodeId = st.get('nodeId') || 999;
var hostPcIp = st.get('hostPcIp');

var msgs = [];
if (dp.becameOffline) {
    msgs.push({
        topic: 'edgelink/alarm/plc_offline/' + dp.devId,
        payload: JSON.stringify({
            alert_type: 'PLC_OFFLINE', node_id: nodeId, device_id: dp.devId,
            device_name: dp.devName, host_pc_ip: hostPcIp,
            msg: dp.devName + ' communication failure: ' + (msg.payload.error || 'unknown'),
            ts: dp.now
        }),
        qos: 1, retain: false
    });
}

var lastGoodTags = st.get('lastGoodTags');
var lastBadSend = st.get('lastBadSend');
if (core.commState.shouldSendBad(lastBadSend[dp.devId], dp.nowMs)
    && lastGoodTags[dp.devId] && lastGoodTags[dp.devId].length > 0) {
    lastBadSend[dp.devId] = dp.nowMs;
    st.set('lastBadSend', lastBadSend);
    var badVals = JSON.parse(JSON.stringify(lastGoodTags[dp.devId]));
    badVals.forEach(function (v) { v.quality = 'BAD'; });
    msgs.push({
        topic: 'edgelink/data/' + nodeId + '/' + dp.devId,
        payload: JSON.stringify({
            node_id: nodeId, device_id: dp.devId, device_name: dp.devName,
            host_pc_ip: hostPcIp, ts: dp.now,
            value_count: badVals.length, values: badVals, quality: 'BAD'
        }),
        qos: 1, retain: false
    });
}

// 释放防重入锁
var guard = st.get('procGuard');
delete guard[dp.devId];
st.set('procGuard', guard);

if (msgs.length === 0) { node.status({ fill: 'grey', shape: 'dot', text: 'nothing to send' }); return null; }
node.status({ fill: 'red', shape: 'dot', text: 'alarm out ×' + msgs.length });
return [msgs];

// 数据管道④成功支路：通断状态恢复（offline→online 记恢复事件）
var core = global.get('edgeCore');
var st = core.createStore(global);
var dp = msg._dp;

var commStatus = st.get('commStatus');
var s = core.commState.onSuccess(commStatus[dp.devId], dp.nowMs);
commStatus[dp.devId] = s.status;
st.set('commStatus', commStatus);

if (s.recovered) {
    var commPending = st.get('commPending');
    commPending.push({ deviceId: dp.devId, success: true, error: '', consecutiveFails: 0, ts: dp.now });
    st.set('commPending', commPending);
    node.status({ fill: 'green', shape: 'dot', text: dp.devName + ' recovered' });
} else {
    node.status({ fill: 'green', shape: 'dot', text: dp.devName + ' online' });
}
return msg;

// 数据管道⑤成功支路：逐点位 变换 + 死区过滤 + 历史缓存
var core = global.get('edgeCore');
var st = core.createStore(global);
var dp = msg._dp;
var result = msg.payload;

var devTags = (st.get('tagConfigs')[dp.devId]) || [];
var lastGoodTags = st.get('lastGoodTags');
var historyData = st.get('historyData');
var stdData = result.data || {};
var nodeId = st.get('nodeId') || 999;
var hostPcIp = st.get('hostPcIp');

var tagValues = [], pgRecords = [], validCount = 0, skippedCount = 0;

devTags.forEach(function (tag) {
    var entry = stdData[tag.id];
    if (!entry || entry.rawValue === undefined || entry.rawValue === null) {
        tagValues.push({   // 本轮未读到：UNCERTAIN 占位
            tag_id: tag.id, tag_address: tag.regAddr || '', tag_name: tag.name || '',
            raw_value: null, eng_value: null, unit: tag.unit || '', quality: 'UNCERTAIN', ts: dp.now
        });
        return;
    }
    var tf = core.transform.applyTransform(entry.rawValue, entry.quality, tag);

    var prev = null;
    var prevVals = lastGoodTags[dp.devId] || [];
    for (var i = 0; i < prevVals.length; i++) { if (prevVals[i].tag_id === tag.id) { prev = prevVals[i]; break; } }

    if (!core.reportFilter.shouldReport({
        prev: prev, eng: tf.eng, deadband: tag.deadband,
        forceIntervalMs: tag.reportForceIntervalMs, triggerKind: dp.triggerKind, nowMs: dp.nowMs
    })) { skippedCount++; return; }

    tagValues.push({
        tag_id: tag.id, tag_address: tag.regAddr || '', tag_name: tag.name || '',
        raw_value: entry.rawValue, register_type: tag.regType || '',
        eng_value: tf.eng, unit: tag.unit || '', quality: tf.quality, ts: dp.now
    });
    validCount++;
    pgRecords.push({
        ts: dp.now, node_id: nodeId, device_id: dp.devId, device_name: dp.devName,
        tag_id: tag.id, tag_address: tag.regAddr || '', tag_name: tag.name || '',
        raw_value: entry.rawValue, register_type: tag.regType || '',
        eng_value: tf.eng, unit: tag.unit || '', quality: tf.quality, host_pc_ip: hostPcIp
    });
    if (!historyData[dp.devId]) historyData[dp.devId] = {};
    if (!historyData[dp.devId][tag.id]) historyData[dp.devId][tag.id] = [];
    historyData[dp.devId][tag.id].push({ ts: dp.now, raw: entry.rawValue, eng: tf.eng, q: tf.quality });
    if (historyData[dp.devId][tag.id].length > 100) historyData[dp.devId][tag.id] = historyData[dp.devId][tag.id].slice(-100);
});

st.set('historyData', historyData);
dp.tagValues = tagValues;
dp.pgRecords = pgRecords;
dp.validCount = validCount;
dp.skippedCount = skippedCount;
node.status({ fill: 'blue', shape: 'dot', text: validCount + ' vals' + (skippedCount ? ' (-' + skippedCount + ')' : '') });
return msg;

// 数据管道⑥成功支路：计算点位求值（追加到 tagValues/pgRecords）
var core = global.get('edgeCore');
var st = core.createStore(global);
var dp = msg._dp;

var calcOut = core.calcTags.evalCalcTags((dp.devInfo && dp.devInfo.calcTags) || [], {
    tagValues: dp.tagValues,
    prevGood: (st.get('lastGoodTags')[dp.devId]) || [],
    lastCalc: st.get('lastCalc'),
    triggerKind: dp.triggerKind,
    nowMs: dp.nowMs, now: dp.now,
    nodeId: st.get('nodeId') || 999,
    devId: dp.devId, devName: dp.devName, hostPcIp: st.get('hostPcIp')
});

dp.tagValues = dp.tagValues.concat(calcOut.values);
dp.pgRecords = dp.pgRecords.concat(calcOut.pgRecords);
dp.validCount += calcOut.values.length;
dp.skippedCount += calcOut.skipped;
st.set('lastCalc', calcOut.lastCalc);
node.status({ fill: 'blue', shape: 'dot', text: 'calc +' + calcOut.values.length });
return msg;

// 数据管道⑦成功支路：lastGoodTags 合并（旧的标 UNCERTAIN，新 GOOD 覆盖）+ 写回
var core = global.get('edgeCore');
var st = core.createStore(global);
var dp = msg._dp;

var lastGoodTags = st.get('lastGoodTags');
var prevGood = lastGoodTags[dp.devId] || [];
var newGood = dp.tagValues.filter(function (v) { return v.quality === 'GOOD'; });

var prevMap = {};
prevGood.forEach(function (pg) {
    prevMap[pg.tag_id] = {
        tag_id: pg.tag_id, tag_address: pg.tag_address, tag_name: pg.tag_name,
        raw_value: pg.raw_value, eng_value: pg.eng_value, unit: pg.unit,
        quality: 'UNCERTAIN', ts: pg.ts
    };
});
newGood.forEach(function (ng) { prevMap[ng.tag_id] = ng; });
var merged = [];
for (var k in prevMap) { if (Object.prototype.hasOwnProperty.call(prevMap, k)) merged.push(prevMap[k]); }

lastGoodTags[dp.devId] = merged;
st.set('lastGoodTags', lastGoodTags);
node.status({ fill: 'blue', shape: 'dot', text: 'lastGood ' + merged.length });
return msg;

// 数据管道⑧成功支路出口：MQTT/PG 输出组装 + 释放 guard（二输出口）
var core = global.get('edgeCore');
var st = core.createStore(global);
var dp = msg._dp;
var nodeId = st.get('nodeId') || 999;

var mqttMsg = null;
if (dp.tagValues.length > 0) {
    mqttMsg = {
        topic: 'edgelink/data/' + nodeId + '/' + dp.devId,
        payload: JSON.stringify({
            node_id: nodeId, device_id: dp.devId, device_name: dp.devName,
            host_pc_ip: st.get('hostPcIp'), ts: dp.now,
            value_count: dp.validCount, values: dp.tagValues
        }),
        qos: 1, retain: false
    };
}
var pgMsg = dp.pgRecords.length > 0 ? { payload: { pgRecords: dp.pgRecords } } : null;

// 释放防重入锁
var guard = st.get('procGuard');
delete guard[dp.devId];
st.set('procGuard', guard);

node.status({
    fill: 'green', shape: 'dot',
    text: dp.devName + ' ' + dp.validCount + ' vals' + (dp.skippedCount > 0 ? ' (' + dp.skippedCount + ' skipped)' : '')
});
node.send([mqttMsg, pgMsg]);
return null;

// 监控①取态：凭据/就绪检查 + 公共上下文（_mon）。未就绪灰灯短路，零网络调用
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
core.logger.setDebug(st.get('debug'));

var apiKey = st.get('apiKey');
if (!apiKey) { node.error('[CM] edge_apiKey not configured'); st.set('configManagerLock', null); return null; }

if (!st.get('configReady')) {
    node.status({ fill: 'grey', shape: 'dot', text: 'wait config' });
    return null;
}

var mem = 0;
try { var pr = global.get('process'); mem = pr ? Math.round(pr.memoryUsage().rss / 1024 / 1024) : 0; } catch (e) { mem = 0; }

// 磁盘 spool 积压字节数（健康指标）
var spoolBytes = 0;
try {
    var _fs = global.get('fs');
    var _path = global.get('path');
    if (_fs && _path) {
        var spoolDir = _path.join(global.get('userDir') || '.', 'edgelink_pg_spool');
        if (_fs.existsSync(spoolDir)) {
            _fs.readdirSync(spoolDir).forEach(function (fname) {
                try { spoolBytes += _fs.statSync(_path.join(spoolDir, fname)).size; } catch (e) {}
            });
        }
    }
} catch (e) { spoolBytes = 0; }

msg._mon = {
    now: new Date().toISOString(),
    mem: mem,
    spoolBytes: spoolBytes,
    nodeId: st.get('nodeId') || 999,
    hostPcIp: st.get('hostPcIp'),
    jwt: st.get('jwt'),
    apiKey: apiKey,
    devices: st.get('devices'),
    reauthSent: false   // 本周期 reauth 去重标记（③⑤⑥ 共享）
};
node.status({ fill: 'blue', shape: 'dot', text: 'mem ' + mem + 'MB' });
return [msg, msg];

// 监控②MQTT心跳组装 → 输出1（edgelink/heartbeat/{nodeId}）
var core = global.get('edgeCore');
var st = core.createStore(global);
var m = msg._mon;

var commStat = st.get('commStatus');
var devList = m.devices.map(function (d) {
    var cs = commStat[d.id] || {};
    return {
        id: d.id, name: d.deviceName,
        online: (cs.consecutiveFails || 0) === 0,
        consecutiveFails: cs.consecutiveFails || 0,
        tagCount: (d.tags || []).length
    };
});

node.status({ fill: 'blue', shape: 'dot', text: 'MQTT HB ×' + m.devices.length });
return {
    topic: 'edgelink/heartbeat/' + m.nodeId,
    payload: JSON.stringify({
        node_id: m.nodeId, host_pc_ip: m.hostPcIp,
        device_count: m.devices.length, devices: devList,
        running_flows: 5, memory_usage_mb: m.mem, status: 'online', ts: m.now
    }),
    qos: 1, retain: false
};

// 监控③HTTP心跳：401检测 + nodeId更新 + kill switch → 输出1 继续支路 / 输出2 reauth
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));
var m = msg._mon;

var params = 'host_pc_ip=' + encodeURIComponent(m.hostPcIp)
    + '&node_ip=' + encodeURIComponent(m.hostPcIp)
    + '&running_flows=5&memory_usage_mb=' + m.mem
    + '&pg_success_count=' + st.get('pgSuccessCount') + '&pg_fail_count=' + st.get('pgFailCount')
    + '&spool_bytes=' + m.spoolBytes
    + (st.get('configVersion') ? '&config_version=' + st.get('configVersion') : '');

core.httpClient.requestJson({
    host: st.get('backendHost'), port: st.get('backendPort'),
    path: '/monitor/heartbeat?' + params, method: 'POST',
    headers: { 'X-API-Key': m.apiKey, 'Authorization': 'Bearer ' + m.jwt, 'Content-Type': 'application/json' },
    body: '{}', timeout: 5000
}).then(function (r) {
    if (r.error) log.debug('Monitor', 'HB err: ' + r.error);
    var reauthMsg = null;
    // 状态清理由心跳 401 独占（原版语义）；reauth 消息按周期去重（③⑤⑥ 共享 m.reauthSent）
    if (r.status === 401 && !st.get('reauthInProgress')) {
        log.warn('Monitor', 'JWT expired (401), trigger re-login');
        st.set('jwt', '');
        st.set('configReady', false);
        st.set('reauthInProgress', true);
    }
    if (r.status === 401 && !m.reauthSent) {
        m.reauthSent = true;
        reauthMsg = { payload: { action: 'reauth' } };
    }
    var j = r.json;
    if (j) {
        var nid = (j.data && j.data.node_id) ? j.data.node_id : 0;
        if (nid > 0 && nid !== m.nodeId) {
            st.set('nodeId', nid);
            log.debug('Monitor', 'nodeId updated: ' + m.nodeId + ' → ' + nid);
        }
        // kill switch 轮询兜底——心跳响应携带 disabled 标志，每周期比对
        var disabledFlag = !!(j.data && j.data.disabled);
        var curDisabled = !!st.get('nodeDisabled');
        if (disabledFlag !== curDisabled) {
            st.set('nodeDisabled', disabledFlag);
            try { core.configCache.setDisabled(global.get('userDir'), disabledFlag); } catch (e) {}
            if (disabledFlag) {
                st.set('devices', []);
                st.set('tagConfigs', {});
                st.set('configReady', false);
                log.warn('Monitor', '⚠ 本节点已被后端停用（心跳轮询发现），采集已停止');
            } else {
                st.set('configReady', false);
                log.warn('Monitor', '✅ 本节点已重新启用（心跳轮询发现），等待下轮配置刷新');
            }
        }
    }
    if (r.status !== null) node.status({ fill: r.status === 200 ? 'green' : 'red', shape: 'dot', text: 'HB ' + r.status });
    node.send([msg, reauthMsg]);
});
return null;

// 监控④逐台在线上报：每台设备单独 POST /monitor/device-comm（fire-and-forget）
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));
var m = msg._mon;

var commStat = st.get('commStatus');
try {
    m.devices.forEach(function (d) {
        var cs = commStat[d.id] || {};
        var ok = (cs.consecutiveFails || 0) === 0 && cs.lastSuccessTime;
        var dp = 'node_id=' + encodeURIComponent(m.nodeId) + '&device_id=' + encodeURIComponent(d.id)
            + '&success=' + (ok ? 'true' : 'false')
            + '&error_msg=' + encodeURIComponent(ok ? '' : 'no recent success');
        core.httpClient.requestJson({
            host: st.get('backendHost'), port: st.get('backendPort'),
            path: '/monitor/device-comm?' + dp, method: 'POST',
            headers: { 'X-API-Key': m.apiKey, 'Authorization': 'Bearer ' + m.jwt, 'Content-Type': 'application/json' },
            body: '{}', timeout: 2000
        });
    });
    if (m.devices.length > 0) log.debug('Monitor', 'Reported ' + m.devices.length + ' devices online');
    node.status({ fill: 'blue', shape: 'dot', text: 'dev online ×' + m.devices.length });
} catch (ex) { log.warn('Monitor', 'reportAllDevicesOnline error: ' + ex.message); }
return msg;

// 监控⑤commPending 批量消费：状态跳变事件逐条 POST；401 → 输出2 reauth（本周期去重）
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));
var m = msg._mon;

var pending = st.get('commPending');
if (pending.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: 'comm -' });
    return [msg, null];
}
st.set('commPending', []);
log.debug('Monitor', 'Draining ' + pending.length + ' device-comm events');

pending.forEach(function (item) {
    var p = 'node_id=' + encodeURIComponent(m.nodeId) + '&device_id=' + encodeURIComponent(item.deviceId)
        + '&success=' + (item.success ? 'true' : 'false')
        + '&error_msg=' + encodeURIComponent(item.error || '');
    core.httpClient.requestJson({
        host: st.get('backendHost'), port: st.get('backendPort'),
        path: '/monitor/device-comm?' + p, method: 'POST',
        headers: { 'X-API-Key': m.apiKey, 'Authorization': 'Bearer ' + m.jwt, 'Content-Type': 'application/json' },
        body: '{}', timeout: 3000
    }).then(function (r) {
        if (r.status === 401 && !st.get('reauthInProgress') && !m.reauthSent) {
            m.reauthSent = true;
            node.send([null, { payload: { action: 'reauth' } }]);
        }
    });
});
node.status({ fill: 'blue', shape: 'dot', text: 'comm ×' + pending.length });
return [msg, null];

// 监控⑥PG统计上报：写库成功/失败计数差值上报；401 → 输出2 reauth（本周期去重）
var core = global.get('edgeCore');
var st = core.createStore(global);
var m = msg._mon;

var pgCount = st.get('pgSuccessCount');
var pgFailCount = st.get('pgFailCount');
var writeCount = pgCount - st.get('pgPrevCount');
var failCount = pgFailCount - st.get('pgFailPrev');
st.set('pgPrevCount', pgCount);
st.set('pgFailPrev', pgFailCount);

var success = (failCount === 0);
var p = 'node_id=' + encodeURIComponent(m.nodeId) + '&success=' + (success ? 'true' : 'false')
    + '&latency_ms=' + st.get('pgLastLatencyMs')
    + '&write_count=' + writeCount + '&device_count=' + m.devices.length
    + '&error_msg=' + encodeURIComponent(st.get('pgLastError') || '');

core.httpClient.requestJson({
    host: st.get('backendHost'), port: st.get('backendPort'),
    path: '/monitor/pg-write?' + p, method: 'POST',
    headers: { 'X-API-Key': m.apiKey, 'Authorization': 'Bearer ' + m.jwt, 'Content-Type': 'application/json' },
    body: '{}', timeout: 3000
}).then(function (r) {
    if (r.status === 401 && !st.get('reauthInProgress') && !m.reauthSent) {
        m.reauthSent = true;
        node.send([null, { payload: { action: 'reauth' } }]);
    }
    node.status({ fill: r.status === 200 ? 'green' : 'red', shape: 'dot', text: 'pg ' + (r.status || 'err') });
});
return null;

// 配置①锁+IP检测：单例锁（60s）+ reauth 等待 + IP/指纹/端口规范化
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));

var isReauth = (msg.payload && msg.payload.action === 'reauth');
var existingJwt = st.get('jwt');

// 单例锁（60s 过期；reauth 最多等 30s）
var lock = st.get('configManagerLock');
if (lock && (Date.now() - lock.ts < 60000)) {
    if (isReauth) {
        if (Date.now() - lock.ts < 30000) {
            log.debug('CM', 'Re-auth waiting for active init (' + (Date.now() - lock.ts) + 'ms old)');
            setTimeout(function () { node.send(msg); }, 2000);
            return null;
        }
        log.debug('CM', 'Lock expired, force takeover for reauth');
    } else {
        log.debug('CM', 'Another init in progress, skip');
        return null;
    }
}
st.set('configManagerLock', { ts: Date.now(), nodeId: node.id });

// IP 检测：st.raw 不套默认值，保持旧 `global.get(...) || ...` 短路语义
var envHostPcIp = st.raw('hostPcIp') || global.get('EDGE_HOST_PC_IP') || '';
var detectedIp = envHostPcIp || core.netUtils.detectIp();
if (envHostPcIp) log.debug('CM', 'Using env edge_hostPcIp=' + envHostPcIp);

var actualPort = global.get('uiPort') || env.get('PORT') || 1880;
var hostPcIp = core.netUtils.normalizeHostPcIp(detectedIp, actualPort);
st.set('hostPcIp', hostPcIp);

msg._cm = {
    hostPcIp: hostPcIp,
    fingerprint: core.netUtils.computeFingerprint(),
    isReauth: isReauth,
    isFirstRun: !existingJwt && !isReauth,
    isRefresh: !isReauth && !!existingJwt
};
node.status({ fill: 'blue', shape: 'dot', text: hostPcIp });
return msg;

// 配置②复查/bootstrap：停用态自愈复查 / 首启 bootstrap 拉凭据 → 输出登录请求 msg（异步出口）
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));
var cm = msg._cm;

// 停用态自愈：复查 bootstrap 是否已重新启用
if (st.get('nodeDisabled')) {
    log.debug('CM', '节点处于停用态，复查 bootstrap 是否重新启用...');
    core.bootstrap.fetchBootstrap({
        host: st.get('backendHost'), port: st.get('backendPort'),
        hostPcIp: cm.hostPcIp, secretKey: st.get('bootstrapSecret'), timeout: 5000
    }).then(function (r) {
        if (r.ok) {
            log.warn('CM', '✅ 节点已被重新启用，恢复采集');
            st.set('nodeDisabled', false);
            try { core.configCache.setDisabled(global.get('userDir'), false); } catch (e) {}
            node.send(buildLogin());
        } else if (r.status !== null) {
            st.set('configManagerLock', null);
            node.status({ fill: 'red', shape: 'ring', text: 'DISABLED by server' });
        } else {
            st.set('configManagerLock', null);
        }
    });
    return null;
}

// 首启：bootstrap 拉凭据
if (cm.isFirstRun) {
    log.debug('CM', 'First run, fetching bootstrap from ' + st.get('backendHost') + ':' + st.get('backendPort'));
    core.bootstrap.fetchBootstrap({
        host: st.get('backendHost'), port: st.get('backendPort'),
        hostPcIp: cm.hostPcIp, secretKey: st.get('bootstrapSecret'), timeout: 5000
    }).then(function (r) {
        if (r.ok) {
            var cfg = r.config;
            st.set('apiKey', cfg.apiKey || '');
            st.set('backendUser', cfg.backendUser || '');
            st.set('backendPass', cfg.backendPass || '');
            st.set('mqttConfig', cfg.mqtt || {});
            if (cfg.hostPcIp) st.set('hostPcIp', cfg.hostPcIp);
            log.debug('CM', 'Bootstrap OK, hostPcIp=' + st.get('hostPcIp'));
            node.send(buildLogin());
        } else if (r.disabled) {
            // 节点已被后端停用：进入停用态，不走本地凭据兜底（kill switch 重启持久化路径）
            log.warn('CM', '⚠ 本节点已被后端停用，采集停止（等待重新启用）');
            st.set('nodeDisabled', true);
            st.set('devices', []);
            st.set('tagConfigs', {});
            st.set('configReady', false);
            st.set('configManagerLock', null);
            try { core.configCache.setDisabled(global.get('userDir'), true); } catch (e) {}
        } else {
            log.debug('CM', 'Bootstrap failed: ' + (r.error || 'unknown'));
            node.send(buildLogin());
        }
    });
    return null;
}

// 刷新/reauth：直接构造登录请求
return buildLogin();

function buildLogin() {
    if (!st.raw('backendHost')) st.set('backendHost', '127.0.0.1');
    if (!st.raw('backendPort')) st.set('backendPort', 9099);
    var apiKey = st.get('apiKey') || global.get('EDGE_API_KEY') || '';
    var backendUser = st.get('backendUser') || global.get('EDGE_BACKEND_USER') || '';
    var backendPass = st.get('backendPass') || global.get('EDGE_BACKEND_PASS') || '';

    if (!apiKey || !backendUser || !backendPass) {
        node.error('[CM] 缺少必需配置：edge_apiKey / edge_backendUser / edge_backendPass，请通过 settings.js 的 functionGlobalContext 或环境变量配置后重启 Node-RED');
        st.set('configManagerLock', null);
        return null;
    }

    st.set('apiKey', apiKey);
    st.set('backendUser', backendUser);
    st.set('backendPass', backendPass);
    if (!st.get('enabledStatus')) st.set('enabledStatus', '0');
    st.set('debug', st.get('debug'));

    if (cm.isFirstRun) {
        st.initAll();
        st.set('startTime', new Date().toISOString());
        log.debug('CM', 'First run, hostPcIp=' + cm.hostPcIp);
    }
    if (cm.isRefresh) log.debug('CM', 'Periodic refresh, configReady stays true');
    if (cm.isReauth) {
        st.set('jwt', '');
        st.set('configReady', false);
        st.set('reauthInProgress', true);
        log.debug('CM', '401 reauth, full re-login');
    }

    msg.url = 'http://' + st.get('backendHost') + ':' + st.get('backendPort') + '/login';
    msg.payload = 'username=' + encodeURIComponent(st.get('backendUser')) + '&password=' + encodeURIComponent(st.get('backendPass'));
    return msg;
}

// 配置③JWT解析+缓存读取：输出1=继续（nodeId反查）/ 输出2=重试调度
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));

var apiKey = st.get('apiKey');
if (!apiKey) { node.error('[CM] edge_apiKey not configured'); st.set('configManagerLock', null); return null; }

// JWT 解析（登录响应在 msg.payload）
var jwtToken = '';
try {
    var r = JSON.parse(msg.payload);
    jwtToken = (r.data && r.data.token) ? r.data.token : (r.token || '');
} catch (e) { jwtToken = ''; }

// 先读本地配置缓存（前移到 JWT 校验之前）——后端不可用时也能用最近配置继续采集
var cached = core.configCache.readCache(global.get('userDir'));
if (cached && cached.disabled === true) {
    st.set('nodeDisabled', true);
    st.set('devices', []);
    st.set('tagConfigs', {});
    st.set('configReady', false);
    log.debug('CM', '节点处于停用状态（缓存标记），保持停止');
} else if (cached && cached.devices && cached.tagConfigs) {
    st.set('devices', cached.devices);
    st.set('tagConfigs', cached.tagConfigs);
    st.set('configReady', true);
    log.debug('CM', 'Loaded config from cache, ' + cached.devices.length + ' devices');
}

if (!jwtToken) {
    log.debug('CM', 'JWT FAIL: ' + (msg.payload || '').substring(0, 80));
    st.set('configManagerLock', null);
    node.status({ fill: 'red', shape: 'ring', text: 'JWT fail, retry' });
    return [null, msg];   // 输出2 → 登录重试调度
}

st.set('jwt', jwtToken);
st.set('reauthInProgress', false);
msg._cm.jwt = jwtToken;
log.debug('CM', 'JWT OK, hostPcIp=' + st.get('hostPcIp'));

// 防重入探测（原版 step2 内的 quirk 复刻：每次进入 attempt+1，5s 内重复触发丢弃）
var gate = core.retryPolicy.probeRetryGate(st.get('retryState'), Date.now());
if (gate.skip) return null;
st.set('retryState', gate.state);

node.status({ fill: 'green', shape: 'dot', text: 'JWT OK' });
return [msg, null];

// 配置④nodeId 反查：心跳注册取 nodeId（异步出口；失败放弃本轮不发）
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));
var cm = msg._cm;

var mem = 0;
try {
    var pr = global.get('process');
    mem = pr ? (Math.round((pr.memoryUsage().rss || 0) / 1048576) || 0) : 0;
} catch (e) { mem = 0; }

var nodeParams = 'host_pc_ip=' + encodeURIComponent(cm.hostPcIp)
    + '&node_ip=' + encodeURIComponent(cm.hostPcIp)
    + '&running_flows=5&memory_usage_mb=' + mem;

core.httpClient.requestJson({
    host: st.get('backendHost'), port: st.get('backendPort'),
    path: '/monitor/heartbeat?' + nodeParams, method: 'POST',
    headers: { 'X-API-Key': st.get('apiKey'), 'Authorization': 'Bearer ' + cm.jwt, 'Content-Type': 'application/json' },
    body: '{}', timeout: 5000
}).then(function (r) {
    var nid = (r.json && r.json.data && r.json.data.node_id) ? r.json.data.node_id : 0;
    if (nid > 0) {
        st.set('nodeId', nid);
        log.debug('CM', 'Node registered, nodeId=' + nid);
        node.status({ fill: 'green', shape: 'dot', text: 'nodeId=' + nid });
        node.send(msg);
    } else {
        // nodeId 获取失败即放弃本轮（下周期自动重试），不编造幽灵 id
        if (r.error) log.debug('CM', 'nodeId err: ' + r.error);
        else log.debug('CM', 'nodeId missing in heartbeat response, abort this round');
        log.warn('CM', 'nodeId unavailable, abort config pull this round');
        st.set('configManagerLock', null);
        st.set('configReady', false);
        st.set('lastConfigTs', new Date().toISOString());
        node.status({ fill: 'red', shape: 'ring', text: 'no nodeId' });
    }
});
return null;

// 配置⑤分页拉取：全局点位快照分页（5000/页，200 页熔断）→ msg._cm.records（异步出口）
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));
var cm = msg._cm;

var PAGE_SIZE = 5000;
var allRecords = [];

function fail(msgText) {
    log.warn('CM', msgText);
    st.set('configManagerLock', null);
    st.set('configReady', false);
    st.set('lastConfigTs', new Date().toISOString());
    node.status({ fill: 'red', shape: 'ring', text: 'fetch fail' });
}

function fetchTagPage(pageNum) {
    if (pageNum > 200) {
        fail('Tag paging exceeded 200 pages, aborting (backend paging params not honored?)');
        return;
    }
    core.httpClient.requestJson({
        host: st.get('backendHost'), port: st.get('backendPort'),
        path: '/plc/config/snapshot/list?pageSize=' + PAGE_SIZE + '&pageNum=' + pageNum,
        method: 'GET',
        headers: { 'Authorization': 'Bearer ' + cm.jwt }, timeout: 10000
    }).then(function (r) {
        if (r.error) { fail('Tag fetch error: ' + r.error); return; }
        var j = r.json;
        if (!j) { fail('Tag API parse error'); return; }
        if (j.code !== 200) { fail('Tag API returned code ' + (j.code || 'unknown') + ', will retry on refresh'); return; }
        if (j.snapshotVersion !== undefined && j.snapshotVersion !== null) {
            st.set('configVersion', j.snapshotVersion);
        }
        var pageRows = j.rows || [];
        allRecords = allRecords.concat(pageRows);
        if (j.hasNext === true || pageRows.length === PAGE_SIZE) {
            fetchTagPage(pageNum + 1);
            return;
        }
        cm.records = allRecords;
        node.status({ fill: 'blue', shape: 'dot', text: 'tags ×' + allRecords.length });
        node.send(msg);
    });
}

fetchTagPage(1);
return null;

// 配置⑥分组+清理+缓存+输出组装：输出1=configMsg（调度器）/ 输出2=MQTT 节点上线
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));
var cm = msg._cm;

// 节点已被后端停用时，忽略本次配置拉取
if (st.get('nodeDisabled')) {
    log.warn('CM', '节点已停用，忽略本次配置拉取（等待重新启用）');
    st.set('devices', []);
    st.set('tagConfigs', {});
    st.set('configReady', false);
    st.set('configManagerLock', null);
    return null;
}

var records = cm.records || [];
if (records.length === 0) {
    log.warn('CM', 'No tags in system');
    st.set('configManagerLock', null);
    st.set('configReady', false);
    st.set('lastConfigTs', new Date().toISOString());
    return null;
}

// 分组 + 本机/启用过滤 + MC 有效地址校验（lib）
var grouped = core.tagConfig.groupByDevice(records, {
    myHostPcIp: cm.hostPcIp,
    enabledStatus: st.get('enabledStatus')
});
grouped.skipped.forEach(function (s) {
    log.debug('CM', 'Device ' + s.deviceName + ' has no valid registers, skipped');
});

st.set('devices', grouped.devices);
st.set('tagConfigs', grouped.tagConfigs);
st.set('configReady', true);
st.set('lastConfigTs', new Date().toISOString());
try {
    core.configCache.writeConfig(global.get('userDir'), grouped.devices, grouped.tagConfigs);
    log.debug('CM', 'Config cached');
} catch (e) {
    log.debug('CM', 'Config cache write failed: ' + e.message);
}

// 清理被移除设备/点位的残留状态（lib）
var validDevIds = {};
grouped.devices.forEach(function (d) { validDevIds[d.id] = true; });
var validTagIds = {};
grouped.devices.forEach(function (d) {
    (d.tags || []).forEach(function (t) { validTagIds[t.id] = true; });
});
var cleaned = core.tagConfig.cleanupStaleState(validDevIds, validTagIds, {
    historyData: st.get('historyData'),
    lastGoodTags: st.get('lastGoodTags'),
    commStatus: st.get('commStatus'),
    commPending: st.get('commPending')
});
st.set('historyData', cleaned.historyData);
st.set('lastGoodTags', cleaned.lastGoodTags);
st.set('commStatus', cleaned.commStatus);
st.set('commPending', cleaned.commPending);
st.set('configManagerLock', null);   // 配置完成，释放锁

var now = new Date().toISOString();
var devList = grouped.devices.map(function (d) {
    return { device_id: d.id, device_name: d.deviceName, tag_count: d.tags.length };
});
var configMsg = {
    payload: { jwt: cm.jwt, nodeId: st.get('nodeId'), hostPcIp: cm.hostPcIp, devices: grouped.devices }
};
var mqttMsg = {
    topic: 'edgelink/nodes/' + st.get('nodeId') + '/status',
    payload: JSON.stringify({
        node_id: st.get('nodeId'), host_pc_ip: cm.hostPcIp, status: 'online',
        device_count: grouped.devices.length, devices: devList, ts: now
    }),
    qos: 1, retain: true
};
log.debug('CM', 'Config complete, ' + grouped.devices.length + ' devices ready');
node.status({ fill: 'green', shape: 'dot', text: 'ready ×' + grouped.devices.length });
node.send([configMsg, mqttMsg]);
return null;

// 配置⑦登录重试调度：retryPolicy 状态机 + 指数退避（120s 熔断档）；成功 → 输出到 nodeId 反查
var core = global.get('edgeCore');
var st = core.createStore(global);
core.logger.setSink(function (level, scope, m) { node.warn('[' + scope + '] ' + m); });
var log = core.logger;
log.setDebug(st.get('debug'));

var plan = core.retryPolicy.planRetry(st.get('retryState'));
st.set('retryState', plan.state);

if (plan.exhausted) {
    if (plan.warnOnce) log.warn('CM', 'Login retry exhausted (5x), next in 120s');
    node.status({ fill: 'red', shape: 'ring', text: 'retry exhausted, 120s' });
    setTimeout(function () {
        st.set('retryState', core.retryPolicy.resetRetry());
        node.send([null, msg]);   // 输出2：重置后重进本节点重新排程
    }, plan.delayMs);
    return null;
}

log.debug('CM', 'Retry login in ' + (plan.delayMs / 1000) + 's (attempt ' + plan.attemptForLog + '/5)...');
node.status({ fill: 'yellow', shape: 'ring', text: 'retry in ' + (plan.delayMs / 1000) + 's' });
setTimeout(function () {
    core.httpClient.requestJson({
        host: st.get('backendHost'), port: st.get('backendPort'),
        path: '/login', method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: 'username=' + encodeURIComponent(st.get('backendUser')) + '&password=' + encodeURIComponent(st.get('backendPass')),
        timeout: 5000
    }).then(function (r) {
        var newJwt = (r.json && r.json.data && r.json.data.token) ? r.json.data.token : ((r.json && r.json.token) || '');
        if (newJwt) {
            st.set('retryState', core.retryPolicy.resetRetry());
            st.set('jwt', newJwt);
            st.set('reauthInProgress', false);
            log.debug('CM', 'Retry login OK, discovering...');
            msg._cm.jwt = newJwt;
            node.send([msg, null]);   // 输出1：成功 → 继续 nodeId 反查
        } else {
            log.debug('CM', 'Retry login failed (attempt ' + plan.attemptForLog + '/5), retrying...');
            node.send([null, msg]);   // 输出2：失败 → 重进本节点排下一次
        }
    });
}, plan.delayMs);
return null;
